<?php

declare(strict_types=1);

require_once __DIR__.'/legacy-migration/ChecklistTemplateAssociation.php';
function associationEnv(string$n):string{$v=getenv($n);if(!is_string($v)||$v==='')throw new RuntimeException('CONFIGURATION_INVALID');return$v;}
set_exception_handler(static function(Throwable$e):never{$allowed=['DEFINITION_VERSION_UNPROVEN','CHECKLIST_TEMPLATE_SNAPSHOT_MISMATCH','CHECKLIST_TEMPLATE_ASSOCIATION_CONFLICT','ACTIVE_BASELINE_NOT_FOUND','CHECKLIST_TEMPLATE_NOT_FOUND'];$reason=in_array($e->getMessage(),$allowed,true)?$e->getMessage():'CHECKLIST_TEMPLATE_LINK_UNAVAILABLE';echo json_encode(['ok'=>false,'reason'=>$reason],JSON_THROW_ON_ERROR),"\n";exit(2);});
$o=getopt('',['legacy-object-id:','template-snapshot-id:','apply']);$legacy=filter_var($o['legacy-object-id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$snapshot=filter_var($o['template-snapshot-id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if($legacy===false||$snapshot===false)throw new InvalidArgumentException('CONFIGURATION_INVALID');
$manifest=json_decode((string)file_get_contents(associationEnv('FMONITOR_PILOT_ACTIVE_MANIFEST')),true,flags:JSON_THROW_ON_ERROR);$prefix=(string)($manifest['processPrefix']??'');$db=new mysqli(associationEnv('FMONITOR_DB_HOST'),associationEnv('FMONITOR_DB_USER'),associationEnv('FMONITOR_DB_PASSWORD'),associationEnv('FMONITOR_DB_NAME'),(int)associationEnv('FMONITOR_DB_PORT'));$db->set_charset('utf8mb4');
$baseline=$db->query("SELECT id,cutover_at FROM `{$prefix}fm2_legacy_active_baselines` WHERE legacy_object_id=".(int)$legacy)->fetch_assoc();$template=$db->query("SELECT snapshot_version,valid_from,content_sha256 FROM `{$prefix}fm2_checklist_template_snapshots` WHERE id=".(int)$snapshot)->fetch_assoc();if(!is_array($baseline)||!is_array($template))throw new OutOfBoundsException(!is_array($baseline)?'ACTIVE_BASELINE_NOT_FOUND':'CHECKLIST_TEMPLATE_NOT_FOUND');
$policy=ChecklistTemplateAssociationPolicy::validate('legacy_active_baseline',(string)$baseline['cutover_at'],(string)$template['valid_from'],(string)$template['snapshot_version'],(string)$template['content_sha256']);if(!$policy['allowed'])throw new DomainException((string)$policy['conflictCode']);
$result=['ok'=>true,'mode'=>isset($o['apply'])?'apply':'dry-run','legacyObjectId'=>(int)$legacy,'associationVersion'=>ChecklistTemplateAssociationPolicy::VERSION,'templateSnapshotId'=>(int)$snapshot,'templateSnapshotVersion'=>$template['snapshot_version'],'templateContentSha256'=>$template['content_sha256'],'effectiveAt'=>$baseline['cutover_at']];
if(isset($o['apply']))$result+=(new ChecklistTemplateAssociationTarget($db,$prefix))->associateActiveBaseline((int)$legacy,(int)$snapshot,gmdate('Y-m-d H:i:s'));echo json_encode($result,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR),"\n";
